import itertools

n = 14
edges = [(0, 2), (0, 3), (0, 4), (0, 5), (0, 9), (0, 11), (0, 12), 
         (1, 2), (1, 3), (1, 4), (1, 5), (1, 8), (1, 9), (1, 12), 
         (2, 5), (2, 8), (2, 9), (3, 13), (4, 5), (4, 6), (4, 7), 
         (4, 8), (4, 9), (4, 10), (5, 6), (5, 7), (5, 11), (5, 13), 
         (7, 8), (7, 9), (7, 11), (7, 12), (9, 11), (9, 12), (10, 11), (11, 13)]

# Check fixed edges
fixed = [(1,4), (1,2), (1,9), (0,3)]
for e in fixed:
    assert e in edges or (e[1], e[0]) in edges, f"Missing fixed edge {e}"
print("Fixed edges present: OK")

# Check min degree
deg = [0]*n
for u,v in edges:
    deg[u] += 1
    deg[v] += 1
print(f"Degrees: {deg}")
assert all(d >= 1 for d in deg), "Some vertex has degree 0"
print("Min degree >= 1: OK")

# Check max clique
max_clique = 0
max_clique_set = None
for r in range(1, 6):
    for subset in itertools.combinations(range(n), r):
        is_clique = True
        for i in range(r):
            for j in range(i+1, r):
                if (subset[i], subset[j]) not in edges and (subset[j], subset[i]) not in edges:
                    is_clique = False
                    break
            if not is_clique:
                break
        if is_clique:
            max_clique = r
            max_clique_set = subset
print(f"Max clique size: {max_clique}, example: {max_clique_set}")
assert max_clique <= 4, f"Max clique is {max_clique}"
print("Max clique <= 4: OK")

# Check chromatic number
colors = [-1]*n
def can_color(v, c):
    for u in range(n):
        if u != v and ((u,v) in edges or (v,u) in edges):
            if colors[u] == c:
                return False
    return True

def backtrack(v):
    if v == n:
        return True
    for c in range(5):
        if can_color(v, c):
            colors[v] = c
            if backtrack(v+1):
                return True
            colors[v] = -1
    return False

if backtrack(0):
    print(f"5-coloring found: {colors}")
    print("Chromatic number <= 5: OK")
else:
    print("Chromatic number > 5!")

print(f"\nTotal edges: {len(edges)}")
print(f"Sorted edges: {sorted(edges)}")
